{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Investment — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fff9f6;--accent:#6a4a3c;--muted:#7b6b66;--card:#fff;--glass:rgba(255,255,255,0.6)}
    html,body{height:100%;margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:var(--accent);background:linear-gradient(180deg,#fff 0%,#fff9f6 100%);}
    header{display:flex;align-items:center;justify-content:space-between;padding:18px 28px;background:transparent}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:46px;height:46px;border-radius:10px;background:linear-gradient(135deg,#e9dcd6,#fbf6f4);display:grid;place-items:center;font-weight:700;color:var(--accent)}
    nav a{margin:0 10px;color:var(--muted);text-decoration:none;font-size:15px}
    .cta{background:var(--accent);color:#fff;padding:10px 14px;border-radius:8px;text-decoration:none}
    main{max-width:1100px;margin:28px auto;padding:30px}

    /* Hero */
    .hero{display:grid;grid-template-columns:1fr 360px;gap:28px;align-items:center}
    .hero .lead{background:linear-gradient(180deg,rgba(106,74,60,0.06),rgba(106,74,60,0.03));padding:28px;border-radius:14px}
    .pill{display:inline-block;background:var(--card);padding:6px 10px;border-radius:999px;font-size:13px;color:var(--muted);margin-bottom:12px}
    h1{margin:6px 0 8px;font-size:28px}
    p.lede{color:var(--muted);margin:0 0 18px}

    /* Pricing cards */
    .plans{display:flex;gap:18px;margin-top:18px}
    .plan{flex:1;background:var(--card);padding:18px;border-radius:12px;box-shadow:0 6px 18px rgba(102,80,72,0.06)}
    .price{font-weight:700;font-size:22px;color:var(--accent)}
    .plan ul{margin:10px 0 14px;padding-left:18px;color:var(--muted)}
    .plan .action{display:inline-block;margin-top:8px;padding:10px 12px;border-radius:10px;background:linear-gradient(90deg,var(--accent),#8a5f4f);color:#fff;text-decoration:none}

    /* Aroma wheel */
    .wheel-wrap{background:var(--card);padding:18px;border-radius:12px;display:flex;gap:18px;align-items:center;box-shadow:0 6px 18px rgba(102,80,72,0.04)}
    .wheel{width:220px;height:220px}
    .notes{flex:1}
    .note-label{display:flex;gap:8px;align-items:center;margin:8px 0}
    .note-dot{width:12px;height:12px;border-radius:50%}
    .note-top .note-dot{background:#f6c6a6}
    .note-mid .note-dot{background:#f1e0b8}
    .note-base .note-dot{background:#cfd8d1}
    .note-desc{color:var(--muted)}

    /* Proof gallery */
    .proof{margin-top:26px;background:linear-gradient(180deg,rgba(250,248,247,0.6),rgba(255,255,255,0.4));padding:18px;border-radius:12px}
    .testi{min-height:72px;display:flex;flex-direction:column;justify-content:center}
    .testi p{margin:0;color:var(--muted)}
    .testi .who{margin-top:8px;font-size:13px;color:var(--accent)}
    .badges{display:flex;gap:10px;margin-top:12px}
    .badge{background:#fff;padding:8px;border-radius:8px;border:1px solid rgba(106,74,60,0.06);font-size:13px;position:relative}
    .badge[data-tip]:hover::after{content:attr(data-tip);position:absolute;left:50%;transform:translateX(-50%);bottom:calc(100% + 8px);background:#222;color:#fff;padding:6px 8px;border-radius:6px;font-size:12px;white-space:nowrap}
    .controls{display:flex;gap:8px;margin-top:10px}
    .controls button{padding:8px 10px;border-radius:8px;border:1px solid rgba(106,74,60,0.08);background:transparent}

    footer{margin-top:28px;padding:18px;text-align:center;color:var(--muted)}

    @media (max-width:880px){
      .hero{grid-template-columns:1fr}
      .plans{flex-direction:column}
    }
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">A</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{CITY}}, {{STATE}}</div>
      </div>
    </div>
    <nav aria-label="Primary">
      <a href="index.html">Nest</a>
      <a href="services.html">Offerings</a>
      <a href="blends.html">Blends</a>
      <a href="shop.html">Apothecary</a>
      <a href="pricing.html">Investment</a>
      <a href="about.html">Origins</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Reach</a>
      <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
    </nav>
  </header>

  <main>
    <section class="hero">
      <div class="lead">
        <span class="pill">Tailored scent support</span>
        <h1>Plans that meet the rhythm of your days</h1>
        <p class="lede">Thoughtful aromatherapy offerings designed for simple integration. Each plan includes oil choices, safety guidance, and short scent rituals you can follow at home. No promises of cure — only scent practices that may support calm and clarity.</p>
        <div class="plans" role="list">
          <div class="plan" role="listitem">
            <div style="font-size:13px;color:var(--muted);">Sampler Session</div>
            <div class="price">$65 — single consult</div>
            <ul>
              <li>30-minute scent conversation</li>
              <li>Home dilution notes + one blend suggestion</li>
            </ul>
            <a class="action" href="book.html#sampler">Choose this</a>
          </div>
          <div class="plan" role="listitem">
            <div style="font-size:13px;color:var(--muted);">Seasonal Support</div>
            <div class="price">$220 — 3-month rhythm</div>
            <ul>
              <li>Monthly check-ins, updated blends</li>
              <li>Guided micro-habits for scent moments</li>
            </ul>
            <a class="action" href="book.html#seasonal">Choose this</a>
          </div>
          <div class="plan" role="listitem">
            <div style="font-size:13px;color:var(--muted);">Signature Scent Plan</div>
            <div class="price">$420 — bespoke program</div>
            <ul>
              <li>Full intake, custom scent profile</li>
              <li>Personalized blend + dilution chart</li>
            </ul>
            <a class="action" href="book.html#signature">Choose this</a>
          </div>
        </div>
      </div>

      <aside>
        <div style="max-width:360px">
          <div style="background:var(--card);padding:14px;border-radius:12px;box-shadow:0 6px 18px rgba(106,74,60,0.04)">
            <h3 style="margin:0 0 6px">Aroma wheel — try a note</h3>
            <div class="wheel-wrap">
              <svg class="wheel" viewBox="0 0 200 200" aria-hidden="true">
                <defs>
                  <linearGradient id="g1" x1="0" x2="1"><stop offset="0" stop-color="#f6c6a6"/><stop offset="1" stop-color="#f0b48c"/></linearGradient>
                  <linearGradient id="g2" x1="0" x2="1"><stop offset="0" stop-color="#f1e0b8"/><stop offset="1" stop-color="#e6d39a"/></linearGradient>
                  <linearGradient id="g3" x1="0" x2="1"><stop offset="0" stop-color="#cfd8d1"/><stop offset="1" stop-color="#bfc9c2"/></linearGradient>
                </defs>
                <!-- Top -->
                <path class="seg top" d="M100 100 L100 10 A90 90 0 0 1 190 100 z" fill="url(#g1)" data-note="Top" data-desc="Bright, fleeting scents that appear first: citrus, herbaceous sparkles; may lift the first impression of a blend."/>
                <!-- Middle -->
                <path class="seg mid" d="M100 100 L190 100 A90 90 0 0 1 100 190 z" fill="url(#g2)" data-note="Middle" data-desc="The body of the scent: floral, spice, or green notes that give character and linger beyond the first breath."/>
                <!-- Base -->
                <path class="seg base" d="M100 100 L100 190 A90 90 0 0 1 10 100 z" fill="url(#g3)" data-note="Base" data-desc="Deep, grounding aromas: woods, resins, musk-like accords; they anchor a blend and persist longest."/>
                <!-- center -->
                <circle cx="100" cy="100" r="28" fill="#fff" stroke="#efe7e3"/>
                <text x="100" y="105" text-anchor="middle" font-size="12" fill="#6a4a3c">Aroma Wheel</text>
              </svg>
              <div class="notes">
                <div class="note-top note-label"><div class="note-dot"></div><strong>Top notes</strong></div>
                <div class="note-mid note-label"><div class="note-dot"></div><strong>Middle notes</strong></div>
                <div class="note-base note-label"><div class="note-dot"></div><strong>Base notes</strong></div>
                <div class="note-desc" id="wheelDesc">Hover a segment to read its quality and examples.</div>
              </div>
            </div>
          </div>

          <div class="proof" style="margin-top:12px">
            <div><strong>What people say</strong></div>
            <div class="testi" id="testi"> 
              <p id="testiText">"Subtle, careful suggestions — I found a ritual I use each morning."</p>
              <div class="who" id="testiWho">— L., designer</div>
            </div>
            <div class="badges">
              <div class="badge" data-tip="2+ decades curating essential oil safety">Practitioner vetted</div>
              <div class="badge" data-tip="Guidance on dilution and patch testing">Safety-first guidance</div>
              <div class="badge" data-tip="Local studio in {{CITY}}, {{STATE}}">Local studio</div>
            </div>
            <div class="controls">
              <button id="prev">◀</button>
              <button id="next">▶</button>
            </div>
          </div>
        </div>
      </aside>
    </section>

    <section style="margin-top:20px;background:var(--card);padding:18px;border-radius:12px">
      <h3 style="margin:0 0 8px">Notes on safety</h3>
      <p style="color:var(--muted);margin:0 0 6px">All recommendations include dilution suggestions and instructions for performing a patch test. If you are pregnant, nursing, have pets, or are under professional care, please mention this during booking — we will offer scent options and safety guidance. Recommendations may support comfort but are not medical advice.</p>
    </section>

    <section style="margin-top:16px;display:flex;gap:12px">
      <a href="book.html" class="cta" style="padding:12px 16px">Reserve a consult</a>
      <a href="contact.html" style="padding:12px 16px;border-radius:10px;border:1px solid rgba(106,74,60,0.06);text-decoration:none;color:var(--accent);background:#fff">Questions? Reach out</a>
    </section>

  </main>

  <footer>
    <div>{{BUSINESS_NAME}} • <a href="tel:{{PHONE}}">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
  </footer>

  <script>
    // Aroma wheel interactivity
    (function(){
      const segs = document.querySelectorAll('.wheel .seg');
      const desc = document.getElementById('wheelDesc');
      segs.forEach(s=>{
        s.addEventListener('mouseenter', ()=>{
          const d = s.getAttribute('data-desc');
          const n = s.getAttribute('data-note');
          desc.textContent = n + ' — ' + d;
          s.style.opacity = '0.95';
          s.style.filter = 'drop-shadow(0 6px 10px rgba(106,74,60,0.12))';
        });
        s.addEventListener('mouseleave', ()=>{
          desc.textContent = 'Hover a segment to read its quality and examples.';
          s.style.opacity = '1';
          s.style.filter = 'none';
        });
      });
    })();

    // Proof gallery rotating testimonials
    (function(){
      const items = [
        {text:'"Subtle, careful suggestions — I found a ritual I use each morning."', who:'L., designer'},
        {text:'"I appreciated the safety notes and the clear dilution guide."', who:'R., parent'},
        {text:'"Details that matter: travel-size options, and a scent I enjoy daily."', who:'M., educator'}
      ];
      let i=0;const tEl=document.getElementById('testiText');const wEl=document.getElementById('testiWho');
      function show(idx){tEl.textContent=items[idx].text;wEl.textContent='— '+items[idx].who}
      show(0);
      let iv = setInterval(()=>{i=(i+1)%items.length;show(i)},5000);
      document.getElementById('prev').addEventListener('click',()=>{i=(i-1+items.length)%items.length;show(i);clearInterval(iv);iv=setInterval(()=>{i=(i+1)%items.length;show(i)},5000)});
      document.getElementById('next').addEventListener('click',()=>{i=(i+1)%items.length;show(i);clearInterval(iv);iv=setInterval(()=>{i=(i+1)%items.length;show(i)},5000)});
    })();
  </script>
</body>
</html>"} 
{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Origins — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fffefb;--accent:#5a3f36;--muted:#6e5c57}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:var(--accent);background:var(--bg)}
    header{display:flex;justify-content:space-between;align-items:center;padding:16px 26px}
    .logo{width:44px;height:44px;border-radius:12px;background:linear-gradient(180deg,#fff,#f8efe9);display:grid;place-items:center}
    nav a{margin:0 10px;color:var(--muted);text-decoration:none}

    main{max-width:980px;margin:24px auto;padding:18px}
    .hero{background:linear-gradient(180deg,#fff,#fff7f2);padding:18px;border-radius:12px}
    .story{display:grid;grid-template-columns:1fr 320px;gap:18px;margin-top:18px}
    .bio{background:#fff;padding:14px;border-radius:12px}
    .side{background:linear-gradient(180deg,#fff,#fffefb);padding:14px;border-radius:12px}

    /* Proof gallery larger */
    .proof{margin-top:14px;padding:12px;border-radius:12px;background:#fff;box-shadow:0 6px 22px rgba(90,63,54,0.04)}
    .carousel{display:flex;align-items:center;gap:14px}
    .quote{flex:1}
    .quote p{margin:0;color:var(--muted);font-size:15px}
    .author{margin-top:8px;font-weight:700;color:var(--accent)}
    .badges{display:flex;flex-wrap:wrap;gap:10px;margin-top:12px}
    .badge{padding:8px 12px;border-radius:10px;background:#fff;border:1px solid rgba(90,63,54,0.06);font-size:13px;position:relative}
    .badge[data-tip]:hover::after{content:attr(data-tip);position:absolute;left:50%;transform:translateX(-50%);bottom:calc(100% + 8px);background:#222;color:#fff;padding:6px 8px;border-radius:6px;font-size:12px}

    footer{margin-top:26px;padding:18px;text-align:center;color:var(--muted)}

    @media (max-width:900px){.story{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;gap:12px;align-items:center">
      <div class="logo">{{BUSINESS_NAME.charAt(0)}}</div>
      <div style="font-weight:700">{{BUSINESS_NAME}}</div>
    </div>
    <nav>
      <a href="index.html">Nest</a>
      <a href="services.html">Offerings</a>
      <a href="blends.html">Blends</a>
      <a href="shop.html">Apothecary</a>
      <a href="pricing.html">Investment</a>
      <a href="about.html">Origins</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Reach</a>
    </nav>
  </header>

  <main>
    <section class="hero">
      <h1 style="margin:0 0 8px">A practice of attention, shaped by scent</h1>
      <p style="margin:0;color:var(--muted)">I create simple scent suggestions and practical blends for moments you want to make clearer, quieter, or more deliberate. Sessions include safety guidance on dilution and patch testing.</p>
    </section>

    <div class="story">
      <article class="bio">
        <h3>Our story</h3>
        <p style="color:var(--muted)">The practice began with small experiments — a few drops on a cotton square, a morning routine refined over months. From those early notes grew a focus on plain, usable scent habits: short rituals you can repeat, blends you can prepare safely at home, and a gently inquisitive intake that prioritizes questions about pregnancy, pets, medications, and sensitivities.</p>

        <div style="margin-top:12px">
          <h4 style="margin:0 0 6px">A few micro-habits</h4>
          <ul style="color:var(--muted)">
            <li>One mindful inhale before email (10–15 seconds)</li>
            <li>Rotate a bedside blend weekly to avoid habituation</li>
            <li>Keep a small roller for travel: 1–2 drops per 5ml carrier</li>
          </ul>
        </div>
      </article>

      <aside class="side">
        <div class="proof">
          <div style="display:flex;justify-content:space-between;align-items:center"><strong>Proof gallery</strong><small style="color:var(--muted)">rotating insights</small></div>
          <div class="carousel" id="carousel">
            <button id="cprev">◀</button>
            <div class="quote" id="qbox">
              <p id="qtext">"Careful guidance — I feel more intentional when I reach for my blend."</p>
              <div class="author" id="qwho">— N., teacher</div>
            </div>
            <div style="width:120px;text-align:center">
              <svg width="100" height="100" viewBox="0 0 100 100" aria-hidden="true">
                <circle cx="50" cy="50" r="48" fill="#fff" stroke="#efe6e1"/>
                <text x="50" y="56" text-anchor="middle" fill="#6a4a3c" font-size="12">Trusted</text>
              </svg>
            </div>
            <button id="cnext">▶</button>
          </div>
          <div class="badges">
            <div class="badge" data-tip="Practical dilution guidance and patch-test instruction">Safety guidance</div>
            <div class="badge" data-tip="Simple blends and storage notes">Blend clarity</div>
            <div class="badge" data-tip="Recommendations that consider pets and pregnancy">Considered recommendations</div>
          </div>
        </div>

        <div style="margin-top:12px;background:#fff;padding:10px;border-radius:10px">
          <h4 style="margin:0 0 8px">Quick facts</h4>
          <p style="margin:0;color:var(--muted)">Appointments include a short intake, safety guidance and a take-home suggestion. Blends come with dilution percentages and storage tips.</p>
        </div>
      </aside>
    </div>

    <section style="margin-top:18px;padding:14px;background:#fff;border-radius:12px">
      <h4 style="margin:0 0 8px">FAQ — safety notes</h4>
      <div style="color:var(--muted)">
        <p style="margin:0 0 8px"><strong>Patch test:</strong> We recommend a patch test for topical blends (apply a small diluted amount to the inner forearm and observe for 24 hours).</p>
        <p style="margin:0 0 8px"><strong>Dilution:</strong> Full dilution instructions accompany any topical suggestion — common guidance: 1–2% for general use, lower for sensitive skin or older adults.</p>
        <p style="margin:0 0 8px"><strong>Pets & pregnancy:</strong> If you have pets, are pregnant, or nursing, mention this during booking so we can suggest pet-safe and pregnancy-conscious options. Recommendations may support comfort but are not medical advice.</p>
      </div>
    </section>

    <section style="margin-top:16px;display:flex;gap:12px">
      <a href="book.html" style="padding:12px 16px;border-radius:10px;background:var(--accent);color:#fff;text-decoration:none">Begin a consult</a>
      <a href="pricing.html" style="padding:12px 16px;border-radius:10px;border:1px solid rgba(90,63,54,0.06);text-decoration:none;color:var(--accent);background:#fff">View plans</a>
    </section>

  </main>

  <footer>
    <div>{{BUSINESS_NAME}} • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> • <a href="tel:{{PHONE}}">{{PHONE}}</a></div>
  </footer>

  <script>
    // Larger rotating proof gallery with badges tooltips (auto-rotate)
    (function(){
      const quotes=[
        {t:'"Careful guidance — I feel more intentional when I reach for my blend."',w:'N., teacher'},
        {t:'"The dilution instruction was realistic and clear."',w:'J., nurse'},
        {t:'"I appreciated the pet-safe options suggested."',w:'S., cat owner'}
      ];
      let idx=0;const t=document.getElementById('qtext'),w=document.getElementById('qwho');
      function flip(i){t.textContent=quotes[i].t;w.textContent=quotes[i].w}
      flip(0);
      let int=setInterval(()=>{idx=(idx+1)%quotes.length;flip(idx)},4000);
      document.getElementById('cprev').addEventListener('click',()=>{idx=(idx-1+quotes.length)%quotes.length;flip(idx);clearInterval(int);int=setInterval(()=>{idx=(idx+1)%quotes.length;flip(idx)},4000)});
      document.getElementById('cnext').addEventListener('click',()=>{idx=(idx+1)%quotes.length;flip(idx);clearInterval(int);int=setInterval(()=>{idx=(idx+1)%quotes.length;flip(idx)},4000)});
    })();
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Reserve — {{BUSINESS_NAME}}</title>
  <style>
    :root{--accent:#5e3f36;--muted:#6d5b57}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:var(--accent);background:#fffaf7}
    header{display:flex;justify-content:space-between;align-items:center;padding:14px 20px}
    nav a{margin:0 10px;color:var(--muted);text-decoration:none}
    main{max-width:920px;margin:22px auto;padding:18px}

    .grid{display:grid;grid-template-columns:1fr 360px;gap:18px}
    .form-card{background:#fff;padding:16px;border-radius:12px;box-shadow:0 8px 26px rgba(94,63,54,0.04)}
    label{display:block;margin-top:10px;font-size:14px}
    input,select,textarea{width:100%;padding:10px;border-radius:8px;border:1px solid #eee;margin-top:6px}
    button.submit{margin-top:14px;padding:12px 14px;border-radius:10px;background:var(--accent);color:#fff;border:none}

    .aside{background:linear-gradient(180deg,#fff,#fff8f5);padding:14px;border-radius:12px}
    .mini-wheel{width:160px;height:160px;margin:0 auto}

    .faq{margin-top:12px;background:#fff;padding:12px;border-radius:10px}
    .faq h4{margin:0 0 8px}
    .note{color:var(--muted);font-size:14px}

    footer{margin-top:18px;text-align:center;color:var(--muted)}

    @media (max-width:900px){.grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div style="font-weight:700">{{BUSINESS_NAME}}</div>
    <nav>
      <a href="index.html">Nest</a>
      <a href="services.html">Offerings</a>
      <a href="blends.html">Blends</a>
      <a href="shop.html">Apothecary</a>
      <a href="pricing.html">Investment</a>
      <a href="about.html">Origins</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Reach</a>
    </nav>
  </header>

  <main>
    <h1 style="margin:0 0 10px">Reserve time</h1>
    <p style="margin:0 0 14px;color:var(--muted)">Select a session type and choose a few times that work for you. We'll confirm availability by email.</p>

    <div class="grid">
      <div class="form-card">
        <form id="booking">
          <label for="name">Full name</label>
          <input id="name" name="name" required>

          <label for="email">Email</label>
          <input id="email" name="email" type="email" required>

          <label for="phone">Phone</label>
          <input id="phone" name="phone" type="tel">

          <label for="type">Session type</label>
          <select id="type" name="type">
